head.script:

scwin.onpageload = function() {
	var dataJson = [
		{"col1":"label1","col2":"value1"},
		{"col1":"label2","col2":"value2"},
		{"col1":"label3","col2":"value3"},
		{"col1":"label4","col2":"value4"},
		{"col1":"label5","col2":"value5"}
	]
	dataList1.setJSON(dataJson);
};

scwin.onpageunload = function() {

};


scwin.trigger1_onclick = function(e) {

	var selectedIndex = select1.getSelectedIndex();

	dataList1.setCellData(selectedIndex, "col1", "테스트");
};

scwin.checkVal1 = function() {
	return WebSquare.wUnit.getDomById('select1').value == '테스트';
}		

scwin.unitTest = function() {
	//init
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('select1').setValue('value2')");
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('select2').setValue('value2')");		
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");		
	WebSquare.wUnit.addCommand("pause", "500");		
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
	WebSquare.wUnit.addCommand("pause", "400");
	//Run  and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest();
